<?php
if ($_SERVER['REQUEST_METHOD']==='POST') define('CSRFCHECK_WITH_TOKEN',1);
require $_SERVER['DOCUMENT_ROOT'].'/main.inc.php';
require_once __DIR__.'/../class/InternalTaskBoardsService.class.php';
header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');
if(GETPOST('errorcode','aZ09')==='InvalidToken'){http_response_code(403);echo json_encode(['ok'=>false,'error'=>'Session token expired. Reload and retry.']);exit;}
try{$svc=new InternalTaskBoardsService($db,$user);if($_SERVER['REQUEST_METHOD']==='GET'){$action=GETPOST('action','aZ09');if($action==='search')$out=['tasks'=>$svc->search(GETPOST('q','alphanohtml'))];elseif($action==='mywork')$out=$svc->myWork();elseif($action==='workspace')$out=$svc->workspace(GETPOSTINT('board'));elseif($action==='shared')$out=['tasks'=>$svc->shared()];else $out=$svc->gallery(GETPOSTINT('archived')===1);}elseif($_SERVER['REQUEST_METHOD']==='POST'){$action=GETPOST('action','aZ09');$raw=GETPOST('payload','none');if(!is_string($raw)||strlen($raw)>100000)throw new RuntimeException('Payload too large.');$d=json_decode($raw,true);if(!is_array($d))throw new RuntimeException('Invalid payload.');if($action==='create_board'&&!preg_match('/^[a-f0-9]{48}$/D',$d['request']??''))throw new RuntimeException('Board request identity required.');$out=$svc->mutate($action,$d);}else {http_response_code(405);throw new RuntimeException('Use GET or POST.');}echo json_encode(['ok'=>true,'data'=>$out],JSON_UNESCAPED_UNICODE|JSON_HEX_TAG);
}catch(InternalTaskAccessException $e){http_response_code(403);echo json_encode(['ok'=>false,'error'=>$e->getMessage()]);}catch(InternalTaskConflictException $e){http_response_code(409);echo json_encode(['ok'=>false,'error'=>$e->getMessage()]);}catch(Throwable $e){if(http_response_code()!==405)http_response_code(422);echo json_encode(['ok'=>false,'error'=>$e->getMessage()]);}$db->close();
